package com.fixflow.mall.service;

import com.fixflow.mall.domain.MallOrder;
import com.fixflow.mall.repo.OrderRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Optional;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
class OrderServiceTest {

    @Mock
    private OrderRepository orderRepository;

    @InjectMocks
    private OrderService orderService;

    private MallOrder orderWithItems;
    private MallOrder orderWithEmptyItems;
    private MallOrder orderWithNullItems;

    @BeforeEach
    void setUp() {
        // 创建有多个item的订单
        orderWithItems = new MallOrder();
        orderWithItems.setId(1L);
        orderWithItems.setUserId(1L);
        orderWithItems.setItemIds(Arrays.asList(101L, 102L, 103L));

        // 创建有空item列表的订单
        orderWithEmptyItems = new MallOrder();
        orderWithEmptyItems.setId(2L);
        orderWithEmptyItems.setUserId(2L);
        orderWithEmptyItems.setItemIds(Collections.emptyList());

        // 创建有null item列表的订单
        orderWithNullItems = new MallOrder();
        orderWithNullItems.setId(3L);
        orderWithNullItems.setUserId(3L);
        orderWithNullItems.setItemIds(null);
    }

    @Test
    @DisplayName("正向测试：验证修复后的方法在有item IDs的订单上能正确返回第一个item ID")
    void firstItemId_OrderWithItems_Success() {
        // 设置mock行为
        when(orderRepository.findById(1L)).thenReturn(Optional.of(orderWithItems));

        // 执行测试
        Long result = orderService.firstItemId(1L);

        // 验证结果
        assertNotNull(result);
        assertEquals(101L, result);
    }

    @Test
    @DisplayName("边界测试：验证原来导致IndexOutOfBoundsException的空item列表输入现在抛出正确的NoSuchElementException")
    void firstItemId_OrderWithEmptyItems_ThrowsNoSuchElementException() {
        // 设置mock行为
        when(orderRepository.findById(2L)).thenReturn(Optional.of(orderWithEmptyItems));

        // 执行测试并验证异常
        org.junit.jupiter.api.function.Executable executable = () -> orderService.firstItemId(2L);

        NoSuchElementException exception = assertThrows(
            NoSuchElementException.class,
            executable
        );

        // 验证异常信息包含正确的信息
        String expectedMessage = "No item IDs found for order 2";
        assertEquals(expectedMessage, exception.getMessage());
    }

    @Test
    @DisplayName("边界测试：验证原来导致IndexOutOfBoundsException的null item列表输入现在抛出正确的NoSuchElementException")
    void firstItemId_OrderWithNullItems_ThrowsNoSuchElementException() {
        // 设置mock行为
        when(orderRepository.findById(3L)).thenReturn(Optional.of(orderWithNullItems));

        // 执行测试并验证异常
        org.junit.jupiter.api.function.Executable executable = () -> orderService.firstItemId(3L);

        NoSuchElementException exception = assertThrows(
            NoSuchElementException.class,
            executable
        );

        // 验证异常信息包含正确的信息
        String expectedMessage = "No item IDs found for order 3";
        assertEquals(expectedMessage, exception.getMessage());
    }

    @Test
    @DisplayName("异常测试：验证当订单不存在时抛出NoSuchElementException")
    void firstItemId_OrderNotFound_ThrowsNoSuchElementException() {
        // 设置mock行为 - 返回空Optional
        when(orderRepository.findById(999L)).thenReturn(Optional.empty());

        // 执行测试并验证异常
        org.junit.jupiter.api.function.Executable executable = () -> orderService.firstItemId(999L);

        assertThrows(
            NoSuchElementException.class,
            executable
        );
    }
}
